# Spec 108: reconciling the proliferation result of the CROP-seq screen with the bulk lines (follow-up of spec107). Proliferation = S.Score + G2M.Score (Seurat CellCycleScoring); NTC - KO, > 0 = less proliferation.
# checks: (1) robustness of the screen effect: bootstrap CI per KO, per guide, fraction of cycling cells (Phase != G1), after regressing nCount and % mito; cells per KO
#         (2) the single NTC of bulk H2052: its score vs the 3 H2052-genotype NTCs labelled H28 (S70N4); NTC - KO in H2052 recomputed with the 4 NTCs
#         (3) is there a KO effect in bulk at all: cc ~ group within each line (R2, F test: do replicates of a KO agree)
#         (4) shared direction: any KO vs NTC -- screen (all KO cells vs NTC) and bulk (lm cc ~ line + KO-vs-NTC; per line)
#         (5) KO-specific ranking: Spearman over the 8 KOs, screen vs each bulk line and vs the bulk median; bulk lines against each other
#         (6) per-KO concordance call: screen (bootstrap CI excludes 0) vs bulk (pooled t-test of spec107 with the corrected H2052 NTC, lines with a drop)
# needs: spec71 audit, spec72 (S70), spec_common.R
# outputs: spec108_proliferation_per_KO.csv, spec108_proliferation_tests.csv, fig23_proliferation_reconcile.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "spec_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); suppressPackageStartupMessages(library(Seurat)); options(width = 220)
fab <- load_full_audited_bulk(); meta <- fab$meta; q <- load_audit(); pr <- readRDS(file.path(OUT, sprintf("spec72_profiles_S70%s.rds", DSUF))); ids <- pr$samples; GR <- c("NTC", KOS); SH <- function(l) sub("NCI-|-211H", "", l)
fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 0), formatC(p, format = "g", digits = 2))); sp <- function(a, b) cor(a, b, method = "spearman"); EXTRA <- c("H28_NTC_R1", "H28_NTC_R2", "H28_NTC_R3")
srt <- load_screen(); g <- as.character(srt$merged_call); md <- srt@meta.data; set.seed(1)
SC <- do.call(rbind, lapply(KOS, function(k) { a <- md$cc[g == "NTC"]; b <- md$cc[g == k]; bs <- replicate(2000, mean(sample(a, replace = TRUE)) - mean(sample(b, replace = TRUE))); r <- resid(lm(cc ~ log10(nCount_RNA) + percent.mt, md))
  data.frame(KO = k, screen_cells = length(b), screen_guides = length(unique(as.character(srt$crispr_calls)[g == k & !grepl("\\|", srt$crispr_calls)])), screen = mean(a) - mean(b), screen_lo = quantile(bs, 0.025), screen_hi = quantile(bs, 0.975),
             screen_cycling_NTC = mean(md$Phase[g == "NTC"] != "G1"), screen_cycling_KO = mean(md$Phase[g == k] != "G1"), screen_adj_nCount = mean(r[g == "NTC"]) - mean(r[g == k]), screen_p = wilcox.test(a, b)$p.value) }))
d <- data.frame(sample = ids, line = meta[ids, "Cell_Line"], group = meta[ids, "Gene_Control"], cc = q[ids, "cc"]); d <- d[d$group %in% GR, ]; dx <- rbind(d, data.frame(sample = EXTRA, line = "NCI-H2052", group = "NTC", cc = q[EXTRA, "cc"]))   # dx = S70 + the 3 extra H2052 NTCs
ntc <- tapply(dx$cc[dx$group == "NTC"], dx$line[dx$group == "NTC"], mean); K <- dx[dx$group %in% KOS, ]; K$d <- as.numeric(ntc[K$line]) - K$cc; BL <- sapply(LINES, function(l) sapply(KOS, function(k) mean(K$d[K$line == l & K$group == k])))
BK <- do.call(rbind, lapply(KOS, function(k) { v <- K$d[K$group == k]; data.frame(KO = k, bulk_median = median(v), bulk_mean = mean(v), bulk_p = t.test(v)$p.value, bulk_lines_drop = sum(BL[k, ] > 0), t(setNames(BL[k, ], paste0("bulk_", SH(LINES))))) }))
R <- merge(SC, BK, by = "KO"); R <- R[match(KOS, R$KO), ]; R$screen_call <- ifelse(R$screen_lo > 0, "drop", ifelse(R$screen_hi < 0, "gain", "none")); R$bulk_call <- ifelse(R$bulk_p < 0.05 & R$bulk_mean > 0 & R$bulk_lines_drop >= 3, "drop", ifelse(R$bulk_p < 0.05 & R$bulk_mean < 0, "gain", "none"))
R$concordant <- R$screen_call == R$bulk_call; write.csv(R, file.path(OUT, "spec108_proliferation_per_KO.csv"), row.names = FALSE)
print(R[, c("KO", "screen_cells", "screen_guides", "screen", "screen_lo", "screen_hi", "screen_cycling_KO", "screen_adj_nCount", "bulk_median", "bulk_mean", "bulk_p", "bulk_lines_drop", paste0("bulk_", SH(LINES)), "screen_call", "bulk_call", "concordant")], digits = 2, row.names = FALSE)
TS <- list(); add <- function(test, est, p) TS[[length(TS) + 1]] <<- data.frame(test = test, estimate = est, p = p)
h <- d$cc[d$line == "NCI-H2052" & d$group == "NTC"]; add("H2052 NTC of S70 (score)", h, NA); add("3 extra H2052-genotype NTCs (mean score)", mean(q[EXTRA, "cc"]), NA); add("H2052 KO samples (mean score)", mean(d$cc[d$line == "NCI-H2052" & d$group != "NTC"]), NA)
for (l in LINES) { e <- d[d$line == l, ]; a <- anova(lm(cc ~ group, e)); add(sprintf("bulk %s: cc ~ group, R2", SH(l)), a$`Sum Sq`[1] / sum(a$`Sum Sq`), a$`Pr(>F)`[1]) }
add("screen: NTC - all KO cells", mean(md$cc[g == "NTC"]) - mean(md$cc[g %in% KOS]), wilcox.test(md$cc[g == "NTC"], md$cc[g %in% KOS])$p.value)
f <- summary(lm(cc ~ line + I(group != "NTC"), dx))$coef; add("bulk 4 lines: NTC - any KO (lm cc ~ line + KO, H2052 with 4 NTCs)", -f[nrow(f), 1], f[nrow(f), 4]); f <- summary(lm(cc ~ line + I(group != "NTC"), d))$coef; add("bulk 4 lines: NTC - any KO (S70, 1 H2052 NTC)", -f[nrow(f), 1], f[nrow(f), 4])
for (l in LINES) { e <- dx[dx$line == l, ]; add(sprintf("bulk %s: NTC - any KO", SH(l)), mean(e$cc[e$group == "NTC"]) - mean(e$cc[e$group != "NTC"]), if (sum(e$group == "NTC") > 1) t.test(e$cc[e$group == "NTC"], e$cc[e$group != "NTC"])$p.value else NA) }
for (l in LINES) { r <- cor.test(R$screen, BL[R$KO, l], method = "spearman", exact = FALSE); add(sprintf("KO ranking: screen vs bulk %s (8 KOs, Spearman)", SH(l)), r$estimate, r$p.value) }
r <- cor.test(R$screen, R$bulk_median, method = "spearman", exact = FALSE); add("KO ranking: screen vs bulk median of the 4 lines", r$estimate, r$p.value); cb <- cor(BL, method = "spearman"); add("KO ranking: bulk lines vs each other (mean of 6 pairs)", mean(cb[upper.tri(cb)]), NA)
r <- cor.test(R$screen, log10(R$screen_cells), method = "spearman", exact = FALSE); add("screen: proliferation drop vs log10 cells recovered per KO", r$estimate, r$p.value)
TS <- do.call(rbind, TS); write.csv(TS, file.path(OUT, "spec108_proliferation_tests.csv"), row.names = FALSE); print(TS, digits = 3, row.names = FALSE)

save_fig("fig23_proliferation_reconcile", 16, 10, function() {
  layout(matrix(1:6, nrow = 2, byrow = TRUE)); par(oma = c(0, 0, 3, 0.4), family = "sans", mar = c(4.8, 4.8, 3.6, 1)); ttl <- function(a, b) { mtext(a, side = 3, adj = 0, line = 1.6, font = 2, cex = 0.82); mtext(b, side = 3, adj = 0, line = 0.5, cex = 0.6, col = INK2) }
  o <- R$KO[order(-R$screen)]; x <- R[match(o, R$KO), ]; lab <- function(at, w = o) text(at, par("usr")[3] - 0.03 * diff(par("usr")[3:4]), w, srt = 45, adj = 1, xpd = NA, cex = 0.82, font = 2, col = KO_COL[w])
  bp <- barplot(x$screen, col = adjustcolor(KO_COL[o], 0.8), border = NA, las = 1, names.arg = rep("", 8), ylim = c(min(0, x$screen_lo) - 0.03, max(x$screen_hi) + 0.1), ylab = "CROP-seq: proliferation score, NTC - KO", cex.axis = 0.8); abline(h = 0, col = INK); segments(bp, x$screen_lo, bp, x$screen_hi, lwd = 1.4, col = INK)
  text(bp, x$screen_hi + 0.012, sprintf("%d cells\n%d guide%s\n%.0f%% cycling", x$screen_cells, x$screen_guides, ifelse(x$screen_guides > 1, "s", ""), 100 * x$screen_cycling_KO), cex = 0.56, adj = c(0.5, 0)); lab(bp)
  ttl("A  CROP-seq: the effect is robust", sprintf("bootstrap 95%% CI; NTC: %d cells, %.0f%% cycling", sum(g == "NTC"), 100 * x$screen_cycling_NTC[1]))
  plot(NA, xlim = c(0.5, 4.5), ylim = range(dx$cc) + c(-0.05, 0.25), xaxt = "n", bty = "n", las = 1, xlab = "", ylab = "bulk: proliferation score of the sample", cex.axis = 0.8)
  for (i in seq_along(LINES)) { e <- dx[dx$line == LINES[i], ]; ko <- e$cc[e$group != "NTC"]; boxplot(ko, at = i + 0.18, add = TRUE, boxwex = 0.3, col = "#d5d4cf", border = INK2, outline = FALSE, axes = FALSE); points(i + 0.18 + seq(-0.1, 0.1, length.out = length(ko)), ko, pch = 21, bg = KO_COL[e$group[e$group != "NTC"]], col = INK2, cex = 0.9)
    nt <- e[e$group == "NTC", ]; points(i - 0.22 + seq(-0.06, 0.06, length.out = nrow(nt)), nt$cc, pch = ifelse(nt$sample %in% EXTRA, 24, 21), bg = ifelse(nt$sample %in% EXTRA, "white", "grey25"), col = INK, cex = 1.4); segments(i - 0.34, mean(nt$cc), i - 0.1, mean(nt$cc), lwd = 2)
    t1 <- TS[TS$test == sprintf("bulk %s: NTC - any KO", SH(LINES[i])), ]; text(i, par("usr")[4], sprintf("NTC - KO %+.2f\np %s", t1$estimate, fp(t1$p)), cex = 0.62, adj = c(0.5, 1)) }
  axis(1, at = 1:4, labels = SH(LINES), tick = FALSE, cex.axis = 0.85); legend("bottomleft", c("NTC (S70)", "extra H2052-genotype NTC", "KO samples"), pch = c(21, 24, 21), pt.bg = c("grey25", "white", "#d5d4cf"), bty = "n", cex = 0.62)
  t2 <- TS[grepl("H2052 with 4 NTCs", TS$test), ]; ttl("B  bulk: NTC vs all KO samples per line", sprintf("the single S70 NTC of H2052 is an outlier vs the 3 other H2052 NTCs; 4 lines: NTC - any KO %+.2f, p = %s", t2$estimate, fp(t2$p)))
  M <- t(BL[o, ]); bp <- barplot(M, beside = TRUE, col = LINE_COL[LINES], border = NA, las = 1, names.arg = rep("", 8), ylab = "bulk: proliferation score, NTC - KO", cex.axis = 0.8, ylim = range(M) + c(-0.05, 0.12)); abline(h = 0, col = INK); lab(colMeans(bp)); legend("topright", SH(LINES), fill = LINE_COL[LINES], border = NA, bty = "n", cex = 0.65, ncol = 2)
  text(colMeans(bp), apply(M, 2, max) + 0.03, sprintf("%d/4\np %s", x$bulk_lines_drop, fp(x$bulk_p)), cex = 0.58, adj = c(0.5, 0), font = ifelse(x$bulk_p < 0.05, 2, 1)); ttl("C  bulk per KO and line (H2052 with its 4 NTCs)", "same KO order as A; n/4 = lines with a drop; p = t-test over the KO samples of the 4 lines")
  plot(R$screen, R$bulk_median, pch = 21, bg = KO_COL[R$KO], col = INK2, cex = 2, bty = "n", las = 1, xlab = "CROP-seq: NTC - KO", ylab = "bulk: NTC - KO, median over the samples of the 4 lines", cex.axis = 0.8, xlim = range(R$screen) + c(-0.03, 0.06), ylim = range(c(0, R$bulk_median)) + c(-0.02, 0.03)); abline(h = 0, v = 0, lty = 2, col = GRID)
  text(R$screen, R$bulk_median, R$KO, pos = 4, cex = 0.66, font = 2, col = KO_COL[R$KO], xpd = NA); t3 <- TS[TS$test == "KO ranking: screen vs bulk median of the 4 lines", ]; ttl("D  per KO: screen vs bulk", sprintf("Spearman %.2f, p = %s (8 KOs)", t3$estimate, fp(t3$p)))
  rr <- sapply(LINES, function(l) TS$estimate[TS$test == sprintf("KO ranking: screen vs bulk %s (8 KOs, Spearman)", SH(l))]); v <- c(rr, cb[upper.tri(cb)]); nm <- c(paste("screen -", SH(LINES)), apply(which(upper.tri(cb), arr.ind = TRUE), 1, function(i) paste(SH(LINES)[i[1]], "-", SH(LINES)[i[2]])))
  par(mar = c(4.8, 8, 3.6, 1)); bp <- barplot(rev(v), horiz = TRUE, col = rev(c(rep("#eb6834", 4), rep("grey55", 6))), border = NA, las = 1, names.arg = rev(nm), cex.names = 0.72, xlab = "Spearman over the 8 KOs (NTC - KO of the proliferation score)", cex.axis = 0.8, xlim = c(-1, 1)); abline(v = 0, col = INK)
  ttl("E  KO ranking: screen vs bulk, and bulk vs bulk", "orange = screen vs a bulk line; grey = two bulk lines")
  par(mar = c(1, 1, 3.6, 1)); plot.new(); plot.window(c(0, 1), c(0, 9.4)); cx <- c(0.02, 0.28, 0.6, 0.86); text(cx, 9, c("KO", "CROP-seq", "bulk (4 lines)", "agree"), font = 2, cex = 0.8, adj = 0)
  for (i in seq_along(o)) { text(cx[1], 9 - i, o[i], col = KO_COL[[o[i]]], font = 2, cex = 0.8, adj = 0); text(cx[2], 9 - i, sprintf("%s (%+.2f)", x$screen_call[i], x$screen[i]), cex = 0.75, adj = 0); text(cx[3], 9 - i, sprintf("%s (%+.2f, %d/4)", x$bulk_call[i], x$bulk_mean[i], x$bulk_lines_drop[i]), cex = 0.75, adj = 0); text(cx[4], 9 - i, ifelse(x$concordant[i], "yes", "no"), cex = 0.8, adj = 0, font = 2, col = ifelse(x$concordant[i], "#1baf7a", "#c0392b")) }
  ttl("F  per-KO call", "screen: bootstrap CI excludes 0; bulk: pooled p < 0.05 with a drop in >= 3 lines")
  mtext("Proliferation after KO: reconciling the CROP-seq screen with the bulk cell lines", outer = TRUE, side = 3, adj = 0, line = 1.5, font = 2, cex = 1)
  mtext("proliferation = S.Score + G2M.Score; NTC - KO, > 0 = less proliferation after the KO; bulk S70, with the 3 H2052-genotype NTCs added for NCI-H2052", outer = TRUE, side = 3, adj = 0, line = 0.3, cex = 0.65, col = INK2)
})
